# generated by tools/ail2py.py from inventory_page_object_main.ail; edit the .ail until onelang s16
import sys

def main() -> int:
    if len(sys.argv) < 5:
        print('usage: inventory_page START STOP STEP FILE...', file=sys.stderr)
        return 2
    rows = inventory_empty()
    i = 4
    try:
        start = int(sys.argv[1])
        stop = int(sys.argv[2])
        step = int(sys.argv[3])
        while i < len(sys.argv):
            inventory_add(rows, sys.argv[i])
            i += 1
        selected = inventory_slice(rows, start, stop, step)
    except (OSError, ValueError):
        print('invalid selection or unreadable input', file=sys.stderr)
        return 2
    print('selected', len(selected), sep='\t')
    for rank, row in enumerate(selected, start=1):
        print(rank, row.path, row.size, sep='\t')
    print('total', inventory_total(selected), sep='\t')
    return 0

if __name__ == "__main__":
    sys.exit(main())
